async function api(path:string,method='GET',body?:unknown){return processing.request(path,method,onTransfer=>requestJSON(path,method,body,csrf,undefined,onTransfer));}

async function download(path:string,filename:string){
 const r=await fetch('/api'+path,{credentials:'same-origin'});
 if(!r.ok){const data=await r.json();throw new Error(data.detail||'The export could not finish.');}
 const disposition=r.headers.get('Content-Disposition')||'';const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i);const plain=disposition.match(/filename="([^"]+)"/i);try{filename=encoded?decodeURIComponent(encoded[1]):plain?.[1]||filename;}catch{}
 const url=URL.createObjectURL(await r.blob());const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
function safeURL(url:unknown){try{const u=new URL(String(url));return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:undefined;}catch{return undefined;}}
function Link({url,children}:{url:unknown;children:React.ReactNode}){const href=safeURL(url);return href?<a href={href} target="_blank" rel="noreferrer">{children} ↗</a>:<span>{children}</span>;}
