 const [resumeId,setResumeId]=useState(''),[session,setSession]=useState<any>(null),[content,setContent]=useState<any>(null),[instructions,setInstructions]=useState(''),[busy,setBusy]=useState(false),[dirty,setDirty]=useState(false),[error,setError]=useState(''),[reviewed,setReviewed]=useState(false),[estimate,setEstimate]=useState<any>(null);
 const choices=workspace.resume.filter(r=>(r.data.job_id||workspace.analysis.find(a=>a.id===r.data.analysis_id)?.data.job_id)===jobId).sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime());
 const selected=choices.find(r=>r.id===resumeId);const current=session?.current;const locked=busy&&activity!=='render';const active=useRef('');active.current=jobId+':'+resumeId;const serial=useRef(0);const lastAction=useRef<any>(null);
 function preferredResume(){if(choices.some(r=>r.id===selectedResumeId))return selectedResumeId;let remembered='';try{remembered=localStorage.getItem('next-step-cover-resume:'+user.id+':'+jobId)||'';}catch{}const submitted=workspace.application.find(a=>a.data.job_id===jobId)?.data.submitted_resume_id;return choices.some(r=>r.id===remembered)?remembered:choices.some(r=>r.id===submitted)?submitted:choices[0]?.id||'';}
 useEffect(()=>{setResumeId(preferredResume());setSession(null);setContent(null);setError('');setDirty(false);},[jobId]);
 useEffect(()=>{if(selectedResumeId&&choices.some(r=>r.id===selectedResumeId))setResumeId(selectedResumeId);},[selectedResumeId]);
 useEffect(()=>{if(!choices.some(r=>r.id===resumeId)&&choices.length){setResumeId(preferredResume());}},[choices.map(r=>r.id).join(',')]);
 function accept(value:any){setSession(value);setContent(value.data.content);setInstructions(value.data.instructions||'');setDirty(false);setReviewed(false);if(value.last_failure)setError(value.last_failure);else if(value.preview_stale)setError('The last preview did not finish. Your inputs are retained; retry to update the PDF.');}
 useEffect(()=>{let live=true;setSession(null);setContent(null);setError('');setDirty(false);setBusy(false);setText('');lastAction.current=null;if(!jobId||!selected||(selected.data.origin==='uploaded'&&!selected.data.source_reviewed))return;const today=new Date();const letter_date=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');api('/cover-letters/workspace','POST',{job_id:jobId,resume_id:resumeId,letter_date}).then(async value=>{if(!live)return;accept(value);if(value.pending_task){setBusy(true);try{await pollTask(value.pending_task,api);if(live)accept(await api('/cover-workspaces/'+value.id));}finally{if(live)setBusy(false);}}}).catch(e=>{if(live)setError(e.message);});return()=>{live=false;};},[jobId,resumeId,selected?.data.source_reviewed]);
 useEffect(()=>{let live=true;if(!session)return;api('/cover-workspaces/'+session.id+'/estimate?mode='+mode).then(v=>live&&setEstimate(v)).catch(()=>{if(live)setEstimate(null);});return()=>{live=false;};},[session?.id,session?.data.version,mode,user.capabilities.ai?.active?.model,user.capabilities.ai?.active?.reasoning_effort]);
 async function act(operation:string,body:any={},asTask=true){if(!session||busy)return;const key=active.current;const startedSerial=serial.current;setActivity(operation);setBusy(true);setError('');lastAction.current={operation,body,asTask};try{const payload={expected_version:session.data.version,...body};const value=asTask?await task('/cover-workspaces/'+session.id+'/'+operation,payload):await api('/cover-workspaces/'+session.id+'/'+operation,'POST',payload);if(active.current===key){if(operation==='render'&&serial.current!==startedSerial){setSession(value);setDirty(true);setReviewed(false);}else accept(value);if(operation==='finalize'||operation==='context/review')await refresh();return value;}}catch(e){if(active.current===key){if(operation!=='render'||serial.current===startedSerial)setError((e as Error).message);try{setSession(await api('/cover-workspaces/'+session.id));}catch{}}}finally{if(active.current===key)setBusy(false);}}
