 useEffect(()=>{if(hasWorkingDraft)return;const groups:any={included:[],supported:[],unknown:[]};for(const k of analysis?.data.keywords||[])groups[k.evidence.length?'supported':'unknown'].push(k);setKeywords(groups);},[analysis?.id,hasWorkingDraft,jobId]);
