 {job&&!editor&&!stagedFile&&<PostingOverview job={job} onEdit={()=>{setDraft({title:job.data.title||'',company:job.data.company||'',description:job.data.description,url:job.data.url||''});setEditingJobId(job.id);setDraftOverview(null);setUploadInfo('');setEditor(true);}}/>}
