 {['required','preferred'].map(group=>{const rows=analysis.data.requirements.filter((r:any)=>r.kind==='qualification'&&r.importance===group);return <section className="comparison-group" key={group}><h3>{group==='required'?'Required qualifications':'Preferred qualifications'} · {rows.length}</h3><p className="small muted">Explicit posting qualifications only. Responsibilities and general competencies are not counted.</p>{rows.length?<div className="requirement-grid">{rows.map(requirementCard)}</div>:<p>No explicit {group} qualifications identified.</p>}</section>;})}
