function ResumePreview({value}:{value:any}){return <article className="resume-paper"><h2>{value.name||'Resume'}</h2>{value.headline&&<p>{value.headline}</p>}{(value.contact_lines||String(value.contact||'').split('\n')).filter(Boolean).map((line:string,i:number)=><p className="resume-contact" key={i}>{line}</p>)}{value.sections.filter((s:any)=>s.entries.length).map((s:any)=><section key={s.title}><h3>{s.title}</h3>{s.entries.map((e:any,i:number)=><div key={i}><h4>{e.title}</h4><p className="resume-detail">{e.details||[e.organization,e.dates].filter(Boolean).join(' | ')}</p><ul>{e.bullets.map((b:string,j:number)=><li key={j}>{b}</li>)}</ul></div>)}</section>)}</article>;}

function Prep(){const {workspace,user,mode,task,refresh}=useApp();return <Skills accountId={user.id} call={api} task={task} workspace={workspace} mode={mode} aiAvailable={user.capabilities.openai_key_source==='account'} refresh={refresh}/>;}

function Jobs(){const {workspace,mode,task,refresh,startApplication,user,busy}=useApp();return <JobSearch key={user.id} accountId={user.id} workspace={workspace} call={api} task={task} refresh={refresh} startApplication={startApplication} mode={mode} aiAvailable={user.capabilities.openai_key_source==='account'} webAvailable={!!user.capabilities.web_search} busy={!!busy}/>;}

